COPY public.account_gisservice (id, slug, title, description, image, long_description, features, benefits, technologies, use_cases, demo_video_url, status, sort_order, created_at, updated_at, explore, pdf_booklet) FROM stdin;
bathymetry-mapping	bathymetry-mapping	Bathymetry Mapping	LiDAR Bathymetry Mapping enables seamless survey of land and water interfaces by processing bathymetric LiDAR data to map underwater topography, riverbeds, and coastal zones.	GIS-services/2.png	LiDAR Bathymetry Mapping enables the seamless survey of land and water interfaces. We process bathymetric LiDAR data to map underwater topography, riverbeds, and coastal zones.\r\n\r\nThis service plays a critical role in coastal management, harbor design, and environmental monitoring. By integrating land and aquatic data, we create a continuous model that accurately represents the coastal environment from terrestrial terrain into underwater landscapes.\r\n\r\nOur bathymetric mapping solutions support marine surveys, coastal infrastructure planning, hydrological studies, and environmental analysis.	["Processing of bathymetric LiDAR data", "Underwater terrain and riverbed mapping", "Coastal zone and shoreline analysis", "Seamless land-to-water terrain modeling", "High-resolution elevation and depth models"]	["Accurate mapping of underwater landscapes", "Improved coastal and marine planning", "Better environmental monitoring and analysis", "Enhanced harbor and infrastructure design", "Seamless integration of terrestrial and aquatic data"]	["LiDAR Processing", "Bathymetric LiDAR", "GIS Mapping", "Remote Sensing"]	[]		active	0	2026-03-12 16:33:33.23682+00	2026-03-12 17:53:54.680811+00	{"title": "Analysis", "subsections": [{"slug": "coastal-zone-analysis", "title": "Coastal Zone Analysis", "images": [], "highlight": "", "use_cases": [], "developers": [], "description": "", "key_benefits": [], "technologies": [], "primary_block": {"title": "", "features": [], "description": ""}, "secondary_block": {"title": "", "features": [], "description": ""}, "short_description": "Analyze coastal landscapes using bathymetric LiDAR data to understand shoreline changes, erosion patterns, and marine terrain structures."}]}	\N
dtm-classification	dtm-classification	DTM Classification	Digital Terrain Model (DTM) classification isolates the bare-earth terrain by analyzing LiDAR laser pulse reflections from vegetation, structures, and ground surfaces.	GIS-services/4.png	Our Digital Terrain Model (DTM) classification isolates the “bare earth” terrain by analyzing LiDAR laser pulse reflections from man-made structures, vegetation, and the ground surface.\r\n\r\nBy distinguishing between multiple LiDAR returns such as upper canopy, intermediate vegetation, and ground points, we derive highly accurate elevation data. This process generates reliable terrain point cloud datasets representing the true ground surface.\r\n\r\nDTM classification is essential for terrain analysis, urban planning, flood modeling, infrastructure design, and environmental studies, providing accurate ground elevation models free from surface objects.	["LiDAR point cloud ground classification", "Separation of vegetation, buildings, and terrain points", "High-precision bare-earth terrain extraction"]	["Highly accurate ground elevation models", "Improved terrain analysis and mapping", "Enhanced GIS modeling and simulation"]	["LiDAR Data Processing", "Point Cloud Classification", "Digital Terrain Model (DTM)"]	[]		active	0	2026-03-12 16:43:45.472136+00	2026-03-12 17:55:32.399092+00	{"title": "Explore", "subsections": [{"slug": "3d-modeling", "title": "3D Modeling", "images": [], "highlight": "", "use_cases": [], "developers": [], "description": "", "key_benefits": [], "technologies": [], "primary_block": {"title": "", "features": [], "description": ""}, "secondary_block": {"title": "", "features": [], "description": ""}, "short_description": "Digital Terrain Model (DTM) classification isolates the bare-earth terrain by analyzing LiDAR laser pulse reflections from vegetation, structures, and ground surfaces."}]}	\N
powerline-feature-extraction	powerline-feature-extraction	Powerline Feature Extraction	Powerline Feature Extraction uses high-resolution LiDAR data to identify transmission lines, towers, and surrounding infrastructure, enabling accurate utility mapping and electrical grid management.	GIS-services/7.png	Powerline feature extraction leverages high-resolution LiDAR datasets combined with targeted field verification to create detailed utility mapping solutions.\r\n\r\nBy analyzing LiDAR point cloud data, we accurately detect transmission towers, conductors, poles, and surrounding infrastructure elements. This enables the creation of precise 2D and 3D models for both transmission and distribution power networks.\r\n\r\nThese datasets support electrical grid design, asset management, vegetation monitoring, and infrastructure maintenance. Our workflows significantly reduce operational costs while improving the accuracy and efficiency of powerline inspection and planning.	["Vegetation proximity and safety clearance analysis"]	["Improved electrical grid planning and maintenance"]	["LiDAR Point Cloud Processing"]	[]		active	0	2026-03-12 17:17:52.472421+00	2026-03-12 17:59:35.253533+00	{"title": "Explore", "subsections": [{"slug": "transmission-line-mapping", "title": "Transmission Line Mapping", "images": [], "highlight": "", "use_cases": [], "developers": [], "description": "Analyze crop health and vegetation structures using UAV LiDAR datasets to improve precision farming and agricultural decision-making.", "key_benefits": [], "technologies": [], "primary_block": {"title": "", "features": [], "description": ""}, "secondary_block": {"title": "", "features": [], "description": ""}, "short_description": "Generate detailed 3D models of transmission lines and towers using LiDAR datasets to support electrical grid monitoring and infrastructure planning."}]}	\N
mls-point-classification	mls-point-classification	MLS Point Classification	MLS Point Classification processes mobile LiDAR point cloud data to identify and label urban features such as road markings, poles, and street furniture for detailed 3D mapping.	GIS-services/6.png	Mobile Laser Scanning (MLS) point classification relies on extracting detailed geometric features from LiDAR point cloud datasets to accurately label complex urban environments.\r\n\r\nOur MLS classification workflows assign object labels to key urban elements such as road markings, poles, street furniture, and infrastructure components. This classification process enables the creation of high-definition 3D urban maps used in transportation planning, smart city development, and autonomous navigation systems.\r\n\r\nBy combining advanced point cloud processing techniques with GIS integration, we generate structured datasets that support infrastructure management, urban planning, and large-scale geospatial analysis.	["Mobile LiDAR point cloud classification", "Urban feature extraction and labeling"]	["Accurate classification of complex urban environments", "Better data for transportation and infrastructure planning"]	["LiDAR Point Cloud Processing", "LiDAR Point Cloud Processing"]	[]		active	0	2026-03-12 16:57:03.796319+00	2026-03-12 17:58:50.37798+00	{"title": "Explore", "subsections": [{"slug": "urban-feature-detection", "title": "Urban Feature Detection", "images": [], "highlight": "", "use_cases": [], "developers": [], "description": "", "key_benefits": [], "technologies": [], "primary_block": {"title": "", "features": [], "description": ""}, "secondary_block": {"title": "", "features": [], "description": ""}, "short_description": "Automatically detect and classify urban infrastructure elements such as poles, road markings, and street furniture from MLS LiDAR datasets."}]}	\N
uav-point-classification	uav-point-classification	UAV Point Classification	UAV Point Classification processes drone-based LiDAR point cloud datasets to identify vegetation structure, canopy height, and individual trees for applications in precision agriculture, forestry, and environmental monitoring.	GIS-services/8.png	UAV point classification leverages drone-based LiDAR point cloud datasets to analyze vegetation structures and environmental landscapes with high accuracy.\r\n\r\nWhile UAV point clouds are often converted into standard raster models such as Digital Elevation Models (DEM) and Digital Surface Models (DSM), our processing workflows unlock their full potential by analyzing raw dense point cloud data.\r\n\r\nThis enables accurate measurement of canopy height, tree crown diameter, and identification of individual trees. These datasets are critical for precision agriculture, forestry management, and environmental monitoring applications.\r\n\r\nOur scalable classification workflows ensure reliable, high-quality geospatial datasets that support agricultural planning, ecosystem monitoring, and sustainable land management.	["Drone-based LiDAR point cloud classification"]	["Improved precision agriculture planning"]	["Point Cloud Processing"]	[]		active	0	2026-03-12 17:15:10.560841+00	2026-03-12 18:00:15.992161+00	{"title": "Explore", "subsections": [{"slug": "precision-agriculture", "title": "Precision Agriculture", "images": [], "highlight": "", "use_cases": [], "developers": [], "description": "Analyze crop health and vegetation structures using UAV LiDAR datasets to improve precision farming and agricultural decision-making.", "key_benefits": [], "technologies": [], "primary_block": {"title": "", "features": [], "description": ""}, "secondary_block": {"title": "", "features": [], "description": ""}, "short_description": ""}]}	\N
corridor-classification	corridor-classification	Corridor Classification	Corridor Classification uses LiDAR data to generate precise 3D models of transportation and utility corridors, enabling vegetation analysis, infrastructure monitoring, and risk assessment.	GIS-services/3.png	Corridor classification leverages LiDAR data to generate highly accurate 3D models of transportation and utility corridors. By processing LiDAR point cloud datasets, we identify and classify features such as roads, railways, powerlines, vegetation, and surrounding infrastructure.\r\n\r\nThese detailed corridor models support vegetation encroachment analysis, infrastructure monitoring, and safety risk assessments. Our customizable workflows allow organizations to analyze specific infrastructure components including wires, spans, poles, and surrounding assets.\r\n\r\nCorridor classification is widely used in transportation planning, utility asset management, infrastructure maintenance, and regulatory compliance to ensure safe and efficient corridor operations.	["LiDAR-based corridor mapping and classification", "Utility and transportation corridor modeling"]	["Improved infrastructure monitoring and maintenance", "Better planning for transportation and utility networks"]	["LiDAR Data Processing"]	[]		active	0	2026-03-12 17:04:32.367839+00	2026-03-12 17:54:31.738305+00	{"title": "Explore", "subsections": [{"slug": "utility-corridor-mapping", "title": "Utility Corridor Mapping", "images": [], "highlight": "", "use_cases": [], "developers": [], "description": "", "key_benefits": [], "technologies": [], "primary_block": {"title": "", "features": [], "description": ""}, "secondary_block": {"title": "", "features": [], "description": ""}, "short_description": "Generate detailed LiDAR-based models of powerline and utility corridors to support asset monitoring, maintenance planning, and vegetation management."}]}	\N
